def _num_prog():
    """Vector-core count of the current device (0 when it cannot be queried)."""
    global _NPROG
    if _NPROG:
        return _NPROG
    try:
        from triton.runtime import driver

        props = driver.active.utils.get_device_properties(torch.npu.current_device())
        try:
            val = props["num_vectorcore"]
        except Exception:
            val = getattr(props, "num_vectorcore", 0)
        val = int(val)
        if val > 0:
            _NPROG = val
        return _NPROG
    except Exception:
        return 0


