# --------------------------------------------------------------------------
# host-side scalar handling
# --------------------------------------------------------------------------
def _f32_rtn(x):
    try:
        return struct.unpack("<f", struct.pack("<f", x))[0]
    except OverflowError:
        return math.copysign(math.inf, x)


def _f16_rtz(x):
    """Round a python float to float16 the way this backend does (toward zero)."""
    try:
        h = struct.unpack("<H", struct.pack("<e", x))[0]
    except OverflowError:
        return math.copysign(math.inf, x)
    sign = h & 0x8000
    mag = h & 0x7FFF
    if mag == 0 or mag >= 0x7C00:
        return struct.unpack("<e", struct.pack("<H", h))[0]
    v = struct.unpack("<e", struct.pack("<H", h))[0]
    if abs(v) > abs(x):
        mag -= 1
        h = sign | mag
    return struct.unpack("<e", struct.pack("<H", h))[0]


def _bf16_rtz(x):
    if x != x:
        return x
    b = _f32_rtn(x)
    bits = struct.unpack("<I", struct.pack("<f", b))[0]
    sign = bits & 0x80000000
    mag = bits & 0x7FFFFFFF
    if mag >= 0x7F800000:
        return b
    return struct.unpack("<f", struct.pack("<I", sign | (mag & 0xFFFF0000)))[0]


def _floor_to_i64(x):
    if isinstance(x, float):
        if x != x or x == math.inf:
            return (1 << 63) - 1
        if x == -math.inf:
            return -(1 << 63)
        x = math.floor(x)
    else:
        x = int(x)
    if x > (1 << 63) - 1:
        return (1 << 63) - 1
    if x < -(1 << 63):
        return -(1 << 63)
    return x


def _scalar_spec(dtype, other):
    """(self_is_f64, kernel payload) for the Scalar overload."""
    if dtype == torch.float64:
        v = float(other)
        if v != v:
            return True, (1 << 63) - 1
        bits = struct.unpack("<q", struct.pack("<d", v))[0]
        key = bits if bits >= 0 else -(bits & _F64_MAG)
        return True, key
    if dtype == torch.float16:
        return False, _f16_rtz(float(other))
    if dtype == torch.bfloat16:
        return False, _bf16_rtz(float(other))
    if dtype == torch.float32:
        return False, _f32_rtn(float(other))
    return False, _floor_to_i64(other)


def _view_dtype(dtype):
    if dtype == torch.bool:
        return torch.int8
    if dtype == torch.float64:
        return torch.int64
    return None


def _launch_shape(esize, numel):
    """(BLOCK, grid) for a grid-stride launch capped by the vector-core count."""
    if esize <= 1:
        base = 16384
    elif esize == 2:
        base = 8192
    elif esize == 4:
        base = 4096
    else:
        base = 2048
    nprog = _num_prog()
    if nprog:
        need = triton.cdiv(numel, nprog)
        block = max(64, triton.next_power_of_2(need))
        if block > base:
            block = base
    else:
        block = base
    if numel < block:
        block = max(64, triton.next_power_of_2(numel))
    nb = triton.cdiv(numel, block)
    if nprog and nb > nprog:
        nb = nprog
    return block, (nb,)


_FASTSHAPE = {}


def _fast_shape(numel, esize):
    """Cached (BLOCK, grid) for the contiguous one-shot/persistent fast path.

    Identical geometry to _launch_shape; only the per-call arithmetic is cached.
    Keyed by pure workload metadata (element count, element size), never by data.
    """
    key = (numel, esize)
    val = _FASTSHAPE.get(key)
    if val is None:
        val = _launch_shape(esize, numel)
        if len(_FASTSHAPE) < 4096:
            _FASTSHAPE[key] = val
    return val


_LAUNCHERS = {}
_DRIVER = None
_KN_RT = None
_DIRECT = True


def _ctx():
    """(stream, runtime knobs) for the current device."""
    global _DRIVER, _KN_RT
    d = _DRIVER
    if d is None:
        from triton.runtime import driver

        d = driver.active
        _DRIVER = d
    rt = _KN_RT
    if rt is None:
        from triton import knobs

        rt = knobs.runtime
        _KN_RT = rt
    stream = d.get_current_stream(d.get_current_device())
    return stream, rt


def _launch_flat(jitfn, key, grid, block, a, b, n, *extra):
    """Launch a unit-stride 3-runtime-argument kernel.

    Reuses the compiled kernel handle and calls its launcher directly, which
    skips Triton's per-call binding/specialization/cache-key work. Launch
    hooks are still honoured whenever they are installed; if the compiled
    handle cannot be built the regular JIT call is used instead.
    """
    global _DIRECT
    if _DIRECT:
        ent = _LAUNCHERS.get(key)
        if ent is None:
            try:
                k = jitfn.warmup(a, b, n, block, *extra, grid=grid)
                init = getattr(k, "_init_handles", None)
                if init is not None:
                    init()
                ent = (k, k.function, k.packed_metadata, grid[0])
            except Exception:
                ent = False
            if len(_LAUNCHERS) < 8192:
                _LAUNCHERS[key] = ent
        if ent:
            try:
                stream, rt = _ctx()
            except Exception:
                _DIRECT = False
            else:
                k, function, pm, g0 = ent
                enter = rt.launch_enter_hook
                exit_ = rt.launch_exit_hook
                if enter is None and exit_ is None and not rt.debug:
                    md = None
                else:
                    md = k.launch_metadata((g0, 1, 1), stream, a, b, n, block, *extra)
                k.greater_(
                    g0,
                    1,
                    1,
                    stream,
                    function,
                    pm,
                    md,
                    enter,
                    exit_,
                    a,
                    b,
                    n,
                    block,
                    *extra,
                )
                return
    jitfn[grid](a, b, n, block, *extra)


def _nd_args(merged, with_v):
    shape = [1] * _MAXRANK
    lstr = [1] * _MAXRANK
    u = [0] * _MAXRANK
    v = [0] * _MAXRANK
    r = len(merged)
    for k in range(r):
        shape[k] = merged[k][0]
        u[k] = merged[k][1]
        if with_v:
            v[k] = merged[k][2]
    acc = 1
    for k in range(r - 1, -1, -1):
        lstr[k] = acc
        acc *= shape[k]
    args = list(shape) + list(lstr) + list(u)
    if with_v:
        args += list(v)
    return args


# --------------------------------------------------------------------------
# entry point
# --------------------------------------------------------------------------
def greater_(self, other, *args, **kwargs):
    # ---- fast path: equal shape + equal dtype + both contiguous ----
    # No broadcasting, no stride math, no merge loop; the kernel takes only
    # (a_ptr, b_ptr, n) as runtime arguments.
    if (
        isinstance(self, torch.Tensor)
        and isinstance(other, torch.Tensor)
        and self.shape == other.shape
    ):
        dt = self.dtype
        if dt == other.dtype and self.is_contiguous() and other.is_contiguous():
            numel = self.numel()
            if numel == 0:
                return self
            if dt == torch.float64:
                block, grid = _fast_shape(numel, 8)
                av = self.view(torch.int64)
                bv = other.view(torch.int64)
                _launch_flat(
                    _k_flat_c64,
                    (
                        1,
                        dt,
                        numel,
                        block,
                        grid[0],
                        av.data_ptr() & 15,
                        bv.data_ptr() & 15,
                    ),
                    grid,
                    block,
                    av,
                    bv,
                    numel,
                    _F64_ONE,
                )
            elif dt == torch.bool:
                block, grid = _fast_shape(numel, 1)
                av = self.view(torch.int8)
                bv = other.view(torch.int8)
                ks = (dt, numel, block, grid[0], av.data_ptr() & 15, bv.data_ptr() & 15)
                if numel % block == 0:
                    _launch_flat(_k_flat_cn, (4,) + ks, grid, block, av, bv, numel)
                else:
                    _launch_flat(_k_flat_c, (0,) + ks, grid, block, av, bv, numel)
            else:
                block, grid = _fast_shape(numel, self.element_size())
                ks = (
                    dt,
                    numel,
                    block,
                    grid[0],
                    self.data_ptr() & 15,
                    other.data_ptr() & 15,
                )
                if numel % block == 0:
                    _launch_flat(_k_flat_cn, (4,) + ks, grid, block, self, other, numel)
                else:
                    _launch_flat(_k_flat_c, (0,) + ks, grid, block, self, other, numel)
            return self

    if not isinstance(self, torch.Tensor):
        raise TypeError("greater_(): self must be a Tensor")

    ndim = self.dim()
    sshape = self.shape
    sstride = self.stride()
    sdt = self.dtype

    is_tensor = isinstance(other, torch.Tensor)
    if is_tensor:
        oshape = other.shape
        try:
            bshape = torch.broadcast_shapes(sshape, oshape)
        except RuntimeError:
            raise
        if tuple(bshape) != tuple(sshape):
            raise RuntimeError(
                "output with shape %s doesn't match the broadcast shape %s"
                % (list(sshape), list(bshape))
            )
        odt = other.dtype
        off = ndim - other.dim()
        ostrides = []
        for i in range(ndim):
            j = i - off
            if j < 0 or oshape[j] == 1:
                ostrides.append(0)
            else:
                ostrides.append(other.stride(j))
    else:
        odt = None
        ostrides = None

    numel = self.numel()
    if numel == 0:
        return self

    dims = []
    for i in range(ndim):
        d = sshape[i]
        if d == 1:
            continue
        dims.append((d, sstride[i], 0 if ostrides is None else ostrides[i]))
    merged = []
    for d, x, y in dims:
        if merged and merged[-1][1] == x * d and merged[-1][2] == y * d:
            pd, px, py = merged[-1]
            merged[-1] = (pd * d, x, y)
        else:
            merged.append((d, x, y))

    block, grid = _launch_shape(self.element_size(), numel)
    sdtype = _view_dtype(sdt)
    self_ptr_t = self if sdtype is None else self.view(sdtype)

    if is_tensor:
        self64 = sdt == torch.float64
        other64 = odt == torch.float64
        if self64 != other64:
            raise RuntimeError(
                "greater_(): mixed float64 operand dtypes are not supported"
            )
        odtype = _view_dtype(odt)
        other_ptr_t = other if odtype is None else other.view(odtype)
        one = _F64_ONE if self64 else 1
        if self64:
            if len(merged) <= 1:
                sa = merged[0][1] if merged else 0
                sb = merged[0][2] if merged else 0
                _k_flat_64[grid](
                    self_ptr_t, other_ptr_t, numel, sa, sb, BLOCK=block, ONE=one
                )
            else:
                _k_nd_64[grid](
                    self_ptr_t,
                    other_ptr_t,
                    numel,
                    *_nd_args(merged, True),
                    NDIM=len(merged),
                    BLOCK=block,
                    ONE=one,
                )
        elif len(merged) <= 1:
            sa = merged[0][1] if merged else 0
            sb = merged[0][2] if merged else 0
            _k_flat[grid](self_ptr_t, other_ptr_t, numel, sa, sb, BLOCK=block)
        else:
            _k_nd[grid](
                self_ptr_t,
                other_ptr_t,
                numel,
                *_nd_args(merged, True),
                NDIM=len(merged),
                BLOCK=block,
            )
        return self

    self64, payload = _scalar_spec(sdt, other)
    if self64:
        one = _F64_ONE
        if len(merged) <= 1:
            sa = merged[0][1] if merged else 0
            _k_flat_64s[grid](self_ptr_t, payload, numel, sa, BLOCK=block, ONE=one)
        else:
            _k_nd_64s[grid](
                self_ptr_t,
                payload,
                numel,
                *_nd_args(merged, False),
                NDIM=len(merged),
                BLOCK=block,
                ONE=one,
            )
    elif len(merged) <= 1:
        sa = merged[0][1] if merged else 0
        _k_flat_s[grid](self_ptr_t, payload, numel, sa, BLOCK=block)
    else:
        _k_nd_s[grid](
            self_ptr_t,
            payload,
            numel,
            *_nd_args(merged, False),
            NDIM=len(merged),
            BLOCK=block,
        )
    return self
